package com.termux.app.workspace;
import org.junit.Test;import java.io.File;import static org.junit.Assert.*;
public class AgentInstructionsTest {
 @Test public void claudeHelperUsesSelectedEnvironmentWithoutCodexBootstrapOrAuthReads(){String c=AgentInstructions.command(new File("/private/files"),"ru","claude","ubuntu");assertTrue(c.contains("ubuntu -- /bin/bash"));assertTrue(c.contains("agent-instructions-claude.md"));assertTrue(c.contains("$HOME/.bashrc"));assertFalse(c.contains("command -v codex"));assertFalse(c.contains("CLAUDE_CONFIG_DIR="));assertFalse(c.contains(".credentials.json"));}
 @Test public void preparationOnlyTargetsUbuntuAiAndKeepsConnectionWrapOutside(){WorkspaceStore.Session s=new WorkspaceStore.Session();s.environment="codex";s.codexEnvironment="ubuntu-ai";String c=AgentInstructions.initialization(s);assertTrue(c.contains("python3 -I"));assertTrue(c.contains("instructions-"));assertFalse(c.contains("/root/.codex"));assertFalse(c.contains("auth.json"));assertFalse(c.contains("kill"));s.codexEnvironment="ubuntu";assertEquals("",AgentInstructions.initialization(s));s.codexEnvironment="termux";assertEquals("",AgentInstructions.initialization(s));}
 @Test public void helperEntersActualUbuntuAiAndInheritedHomeWithoutInstalling(){String c=AgentInstructions.command(new File("/private app/files"),"en");assertTrue(c.contains("proot-distro login --bind"));assertTrue(c.contains("ubuntu-ai -- /bin/bash"));assertTrue(c.contains("$HOME/.bashrc"));assertFalse(c.contains("CODEX_HOME="));assertFalse(c.contains("apt install"));assertFalse(c.contains("pkill"));assertFalse(c.contains("killall"));assertTrue(c.contains("agent-instructions-ubuntu-ai.en.md"));}
 @Test public void storageSectionRecognitionWorksInBothLanguagesWithoutInventingSections(){assertTrue(AgentInstructions.hasStorageAddition("Prefix\n## File and temporary data storage\r\nRules"));assertTrue(AgentInstructions.hasStorageAddition("## Хранение файлов и временных данных\nПравила"));assertFalse(AgentInstructions.hasStorageAddition("Discussion of File and temporary data storage"));assertEquals("## File and temporary data storage\nRules",AgentInstructions.storageAddition("prefix\n## File and temporary data storage\nRules"));}
 @Test public void legacyCodexRoutesToShownUbuntuOrNativeTermuxWithoutAiRedirect(){
  String ubuntu=AgentInstructions.command(new File("/private/files"),"en","codex","ubuntu");assertTrue(ubuntu.contains("ubuntu -- /bin/bash"));assertFalse(ubuntu.contains("ubuntu-ai --"));
  String termux=AgentInstructions.command(new File("/private/files"),"en","codex","termux");assertFalse(termux.contains("proot-distro"));assertTrue(termux.contains("--noprofile --norc -i -c"));assertTrue(termux.contains("agent-instructions.py"));assertFalse(termux.contains("ubuntu-ai --"));
  WorkspaceStore.Session old=new WorkspaceStore.Session();old.environment="codex";old.codexEnvironment="termux";assertEquals("termux",AgentInstructionsUi.runtime(old));assertEquals("ubuntu-ai",AgentInstructionsUi.runtime(null));assertEquals("termux",AgentInstructionsUi.fileProfile("termux").environment);old.environment="ubuntu";old.codexEnvironment="ubuntu";assertEquals("ubuntu",AgentInstructionsUi.runtime(old));
 }

}
